package POLYMORPHISM;class student {    int sum;    String name;    student(int a,int b){        sum=a+b;        System.out.println(sum);    }    student(int a,int b,int c){        sum=a+b+c;        System.out.println(sum);    }    student(String name){        this.name=name;    }    public void display(){        System.out.println(name);    }    }    class METHODOVERLOADING{    public static void main(String[] args){        student obj1=new student(10,20);        student obj2=new student(10,20,30);        student obj3=new student("aman");        obj3.display();    }    }